sys_script_include.script:
var CarRentalAjax = Class.create()
CarRentalAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    /**
     * Returns the rent of a car as JSON:
     * { found: boolean, name: string, rent: number, rent_display: string }
     */
    getCarRent: function () {
        var carId = this.getParameter('sysparm_car_id')

        // Never trust client input.
        if (!carId || String(carId).length !== 32) {
            return JSON.stringify({ found: false })
        }

        var car = new GlideRecord('x_2203703_car_re_0_car')
        car.addQuery('sys_id', String(carId))
        car.setLimit(1)
        car.query()

        if (!car.next()) {
            return JSON.stringify({ found: false })
        }

        // Currency fields are stored as "CODE;amount".
        var raw = String(car.getValue('rent') || '0')
        if (raw.indexOf(';') > -1) {
            raw = raw.split(';')[1]
        }

        return JSON.stringify({
            found: true,
            name: car.getDisplayValue('name'),
            rent: parseFloat(raw) || 0,
            rent_display: car.getDisplayValue('rent'),
            available: car.getValue('available') === '1',
        })
    },

    type: 'CarRentalAjax',
})
